#include <set>
#include <string>
#include <iostream>

// Correct SWO: Case-insensitive comparison
struct CaseInsensitiveCompare {
    bool operator()(const std::string& a, const std::string& b) const {
        // Assumes proper locale handling for real-world use
        size_t len = std::min(a.length(), b.length());
        return std::lexicographical_compare(
            a.begin(), a.end(), 
            b.begin(), b.end(), 
            [](char ca, char cb) { return std::tolower(ca) < std::tolower(cb); }
        );
    }
};

int main() {
    // std::set uses CaseInsensitiveCompare as its sorting criterion
    std::set<std::string, CaseInsensitiveCompare> s;
    s.insert("Apple");
    s.insert("apple"); // Equivalent to "Apple" under SWO, only one stored
    // Size is 1, proving equivalence is handled correctly.
}
